function daysInclusive(start,end,month){const s=new Date(`${start}T00:00:00`), e=new Date(`${end}T00:00:00`);const ms=new Date(`${month}-01T00:00:00`);const me=new Date(ms.getFullYear(),ms.getMonth()+1,0);const a=s<ms?ms:s,b=e>me?me:e;return a>b?0:Math.floor((b-a)/86400000)+1}
function dateSet(start,end,month){const s=new Date(`${start}T00:00:00`),e=new Date(`${end}T00:00:00`),ms=new Date(`${month}-01T00:00:00`),me=new Date(ms.getFullYear(),ms.getMonth()+1,0),a=s<ms?ms:s,b=e>me?me:e,set=new Set();for(let d=new Date(a);d<=b;d.setDate(d.getDate()+1))set.add(d.toISOString().slice(0,10));return set}
