const baseRenderRecords=renderRecords;
renderRecords=function(){baseRenderRecords();records.filter(r=>r.newProductTest).forEach(r=>{const select=productionCards.querySelector(`[data-id="${r.id}"] [data-line-record-product]`);if(!select||select.tagName!=='SELECT')return;const input=document.createElement('input');input.className=select.className;input.type='text';input.dataset.lineRecordProduct=select.dataset.lineRecordProduct;input.value=r.product||'';input.placeholder='신제품명 직접 입력';input.addEventListener('input',()=>{r.product=input.value;saveState()});input.addEventListener('blur',()=>{r.product=input.value.trim()||'신제품';input.value=r.product;saveState();renderConditions()});select.replaceWith(input)})};
document.addEventListener('click',event=>{const button=event.target.closest('[data-new-product-test]');if(!button)return;setTimeout(()=>{const r=records.find(x=>x.id===button.dataset.newProductTest),select=r&&productionCards.querySelector(`[data-id="${r.id}"] [data-line-record-product]`);if(!r?.newProductTest||!select||select.tagName!=='SELECT')return;const input=document.createElement('input');input.className=select.className;input.type='text';input.dataset.lineRecordProduct=select.dataset.lineRecordProduct;input.value=r.product||'';input.placeholder='신제품명 직접 입력';input.addEventListener('input',()=>{r.product=input.value;saveState()});input.addEventListener('blur',()=>{r.product=input.value.trim()||'신제품';input.value=r.product;saveState();renderConditions()});select.replaceWith(input);input.focus();input.select()},0)});
function refreshFillAverage(recordId,processKey){const r=records.find(x=>x.id===recordId);if(!r)return;const c=r.conditions[processKey];c.fill=(Number(c.fillTop||0)+Number(c.fillMid||0)+Number(c.fillBottom||0))/3;const avg=conditionCards.querySelector(`[data-average="${recordId}"][data-p="${processKey}"]`);if(avg)avg.innerHTML=`<small>평균 충진량</small><strong>${fmt(c.fill,1)} kg</strong>`;if(processKey==='mainA'){r.conditions.mainB.fillTop=c.fillTop;r.conditions.mainB.fillMid=c.fillMid;r.conditions.mainB.fillBottom=c.fillBottom;r.conditions.mainB.fill=c.fill}}
function renderConditions(){const lineState=getLineState();const visibleRecords=records.filter(r=>lineState[r.line]?.active);conditionCards.innerHTML=visibleRecords.length?visibleRecords.map(r=>{const enabledProcesses=INPUT_PROCESSES.filter(p=>p.key==='mainA'?r.enabled.mainA&&r.enabled.mainB:r.enabled[p.key]);return `<div class="condition-card"><div class="condition-card-title"><div><h4>${r.line} · ${r.product}</h4><small>${r.start} ~ ${r.end}</small></div><span class="condition-summary">${enabledProcesses.length}개 공정</span></div>${enabledProcesses.length?`<div class="condition-process-list">${enabledProcesses.map(p=>{const c=r.conditions[p.key];return `<div class="condition-process-group"><div class="condition-process-header"><strong>${p.inputName||p.name}</strong><span>${p.inlet}/${p.outlet} Hz</span></div><div class="fill-row"><label><span>상단</span><input class="condition-input" data-cid="${r.id}" data-p="${p.key}" data-c="fillTop" type="number" step="0.1" value="${c.fillTop}"></label><label><span>중단</span><input class="condition-input" data-cid="${r.id}" data-p="${p.key}" data-c="fillMid" type="number" step="0.1" value="${c.fillMid}"></label><label><span>하단</span><input class="condition-input" data-cid="${r.id}" data-p="${p.key}" data-c="fillBottom" type="number" step="0.1" value="${c.fillBottom}"></label><div class="average-fill" data-average="${r.id}" data-p="${p.key}"><small>평균 충진량</small><strong>${fmt(c.fill,1)} kg</strong></div></div><div class="condition-secondary"><label><span>소성시간 (hr)</span><input class="condition-input" data-cid="${r.id}" data-p="${p.key}" data-c="time" type="number" step="0.1" value="${c.time}"></label><label><span>로 온도 (°C)</span><input class="condition-input" data-cid="${r.id}" data-p="${p.key}" data-c="temp" type="number" step="1" value="${c.temp}"></label></div></div>`}).join('')}</div>`:'<p class="muted">생산기간 및 생산량 입력에서 운전 공정을 선택하세요.</p>'}</div>`}).join(''):'<p class="muted">생산기간 및 생산량 입력에서 가동 라인을 체크하면 공정별 운전조건이 표시됩니다.</p>';conditionCards.querySelectorAll('[data-cid]').forEach(el=>el.addEventListener('input',()=>{const r=records.find(x=>x.id===el.dataset.cid);const v=Number(el.value);r.conditions[el.dataset.p][el.dataset.c]=v;if(el.dataset.c.startsWith('fill'))refreshFillAverage(r.id,el.dataset.p);if(el.dataset.p==='mainA'&&el.dataset.c.startsWith('fill'))refreshFillAverage(r.id,'mainB');if(el.dataset.p==='mainA'&&!el.dataset.c.startsWith('fill'))r.conditions.mainB[el.dataset.c]=v;saveState()}))}
const trainedModels={...(window.POWER_MODELS?.models||{}),...(window.POWER_MODELS_UTILITY_V4||{})};
function polynomialInput(model,season,numbers){const base=[...model.levels.map(v=>season===v?1:0),...numbers],out=[...base];for(let i=0;i<base.length;i++)for(let j=i;j<base.length;j++)out.push(base[i]*base[j]);return out.map((v,j)=>(v-(model.mu[j]??0))/(model.sd[j]||1))}
function predictModelClass(modelKey,season,numbers){const m=trainedModels[modelKey];if(!m)return {classNo:1,median:0,range:'모델 미연결',idx:0};const x=polynomialInput(m,season,numbers);const scores=m.W.map((w,c)=>m.B[c]+w.reduce((s,v,j)=>s+v*x[j],0)),idx=scores.indexOf(Math.max(...scores));return {classNo:idx+1,idx,median:(modelSettings[modelKey]?.medians?.[idx]??m.medians[idx]),range:m.ranges[idx]||`${m.bounds[idx-1]||0} 초과`,scores}}
function sharedCondition(rec,proc){return proc.key==='mainB'?rec.conditions.mainA:rec.conditions[proc.key]}
// 본소성A/B는 동일 설비이므로 본소성A/B 통합 모델(현재 mainA 모델)을 함께 사용한다.
function predictFurnace(rec,proc,days,season=seasonFromMonth(monthPicker.value)){const c=sharedCondition(rec,proc),modelKey=(proc.key==='mainA'||proc.key==='mainB')?'mainA':proc.key,pred=predictModelClass(modelKey,season,[Number(c.fill),Number(c.time),Number(c.temp),proc.inlet,proc.outlet]);return {classNo:pred.classNo,median:pred.median,range:pred.range,energy:pred.median*days,process:proc.name} }
function predictUtilityDaily(season,cfaTotal,airTotal,lineCount){const out={};[['airCompressor','Air Compressor'],['refrigeratedDryer','냉동식 Dryer'],['adsorptionDryer','흡착식 Dryer'],['co2Removal','CO2 Removal']].forEach(([key,name])=>{const pred=predictModelClass(key,season,[cfaTotal,airTotal,lineCount]);out[name]={...pred,kwh:pred.median}});return out}
function monthDates(month){const [y,m]=month.split('-').map(Number),last=new Date(y,m,0).getDate();return Array.from({length:last},(_,i)=>`${month}-${String(i+1).padStart(2,'0')}`)}
function calculate(){const lineState=getLineState(),active=LINES.filter(l=>lineState[l].active);if(!records.length){alert('생산 기록을 하나 이상 추가해주세요.');return}const month=monthPicker.value,days=monthDates(month),recordDates=new Map(records.map(r=>[r.id,dateSet(r.start,r.end,month)])),detailMap=new Map(),furnaceByLine=Object.fromEntries(active.map(l=>[l,0])),auxByLine=Object.fromEntries(active.map(l=>[l,0])),util={'Air Compressor':0,'냉동식 Dryer':0,'흡착식 Dryer':0,'CO2 Removal':0};let airTotal=0;records.filter(r=>lineState[r.line]?.active).forEach(r=>detailMap.set(r.id,{r,days:0,furnace:0,aux:0,utility:0,predictions:PROCESSES.filter(p=>r.enabled[p.key]).map(p=>predictFurnace(r,p,1))}));for(const day of days){const activeEntries=[...detailMap.values()].filter(x=>recordDates.get(x.r.id)?.has(day));const activeLines=[...new Set(activeEntries.map(x=>x.r.line))];if(!activeLines.length)continue;const season=seasonFromMonth(day),cfaTotal=activeLines.reduce((s,l)=>s+Number(lineState[l].cfa||0),0),cdaTotal=activeLines.reduce((s,l)=>s+Number(lineState[l].cda||0),0),airDay=cfaTotal+cdaTotal;airTotal+=airDay;const utilPred=predictUtilityDaily(season,cfaTotal,airDay,activeLines.length),utilDay=Object.fromEntries(Object.entries(utilPred).map(([k,v])=>[k,v.kwh]));Object.keys(util).forEach(k=>util[k]+=utilDay[k]||0);const furnaceDayByLine=Object.fromEntries(activeLines.map(l=>[l,0])),utilityBasisDayByLine=Object.fromEntries(activeLines.map(l=>[l,0]));activeEntries.forEach(x=>{x.days+=1;const procPred=PROCESSES.filter(p=>x.r.enabled[p.key]).map(p=>predictFurnace(x.r,p,1,season));x._dayFurnace=procPred.reduce((s,p)=>s+p.energy,0);x._dayUtilityBasis=procPred.filter(p=>['예비소성','본소성A','본소성B'].includes(p.process)).reduce((s,p)=>s+p.energy,0);x.furnace+=x._dayFurnace;x.aux+=AUX_DAILY_KWH[x.r.line]||12000;furnaceDayByLine[x.r.line]+=x._dayFurnace;utilityBasisDayByLine[x.r.line]+=x._dayUtilityBasis;x.predictions=procPred});const plantUtilityBasis=Object.values(utilityBasisDayByLine).reduce((s,v)=>s+v,0),utilityDayTotal=Object.values(utilDay).reduce((s,v)=>s+v,0);activeEntries.forEach(x=>{const lineShare=plantUtilityBasis?utilityBasisDayByLine[x.r.line]/plantUtilityBasis:0;const sameLineEntries=activeEntries.filter(y=>y.r.line===x.r.line),sameLineBasis=sameLineEntries.reduce((s,y)=>s+(y._dayUtilityBasis||0),0),productShare=sameLineBasis?(x._dayUtilityBasis||0)/sameLineBasis:0;x.utility+=utilityDayTotal*lineShare*productShare});Object.entries(furnaceDayByLine).forEach(([line,v])=>furnaceByLine[line]+=v);activeEntries.forEach(x=>{x.total=x.furnace+x.aux+x.utility})}const details=[...detailMap.values()].filter(x=>x.days>0);details.forEach(x=>{x.intensity=x.r.qty?x.total/x.r.qty:0;delete x._dayFurnace;delete x._dayUtilityBasis});const utilTotal=Object.values(util).reduce((s,v)=>s+v,0),totalFurnace=Object.values(furnaceByLine).reduce((s,v)=>s+v,0);lastResult={details,util,airTotal,totalFurnace,utilTotal,furnaceByLine,auxByLine};renderResults();saveState()}
function renderTariffEstimate(kwh){const panel=document.getElementById('tariffPanel');if(!panel)return;const t=calculateTariff(monthPicker.value,kwh);panel.innerHTML=`<div class="tariff-total"><small>${monthPicker.value} · ${t.season} · 예상 총 전력요금</small><strong>${fmt(t.total,0)}원</strong><span>예상 사용량 ${fmt(kwh,0)} kWh · 요금적용전력 ${fmt(t.chargePower,0)} kW</span></div><div class="tariff-lines"><div class="tariff-line"><small>기본요금</small><strong>${fmt(t.baseCharge,0)}원</strong></div><div class="tariff-line"><small>전력 사용요금</small><strong>${fmt(t.usageCharge,0)}원</strong></div><div class="tariff-line"><small>기후환경·연료비</small><strong>${fmt(t.climateCharge+t.fuelCharge,0)}원</strong></div><div class="tariff-line"><small>전력기금·부가세</small><strong>${fmt(t.fund+t.vat,0)}원</strong></div><p class="tariff-note">파일의 부하 비율(중간 32%·최대 18%·경부하 50%)과 선택 월의 계절별 단가를 적용했습니다. 역률요금은 입력값이 없어 0원으로 계산합니다.</p></div>`}
function renderResults(){const {details,totalFurnace,utilTotal}=lastResult;const total=details.reduce((s,x)=>s+x.total,0),qty=details.reduce((s,x)=>s+Number(x.r.qty||0),0),auxTotal=details.reduce((s,x)=>s+x.aux,0),directTotal=totalFurnace+auxTotal;kpiGrid.innerHTML=[['총 전력량',fmt(total),'kWh'],['총 생산량',fmt(qty,0),'kg'],['전력 원단위',fmt(qty?total/qty:0,3),'kWh/kg'],['공무동 예측',fmt(utilTotal),'kWh']].map(x=>`<div class="kpi"><div class="kpi-label">${x[0]}</div><div class="kpi-value">${x[1]}<span class="kpi-unit">${x[2]}</span></div></div>`).join('');renderTariffEstimate(total);resultBody.innerHTML=details.map(x=>`<tr><td>${x.r.line}</td><td>${x.r.product}</td><td>${fmt(x.r.qty,0)}</td><td>${fmt(x.furnace)}</td><td>${fmt(x.aux)}</td><td>${fmt(x.utility)}</td><td>${fmt(x.total)}</td><td>${fmt(x.intensity,3)}</td></tr>`).join('');status('계산 완료',true);renderPowerComposition(directTotal,utilTotal,total);renderDonut(details);renderBars(details)}
function renderPowerComposition(directTotal,utilityTotal,total){const directPct=total?directTotal/total*100:0,utilityPct=total?utilityTotal/total*100:0;powerComposition.innerHTML=`<div class="composition-total"><strong>총 ${fmt(total)} kWh</strong><span>제품 생산에 배부되는 전체 전력</span></div><div class="stacked-power-bar" aria-label="설비 직접전력 ${fmt(directPct,1)}%, 공무동(유틸동) 전력 ${fmt(utilityPct,1)}%"><div class="power-segment direct" style="width:${directPct}%"><span>설비 직접전력</span><b>${fmt(directPct,1)}%</b></div><div class="power-segment utility" style="width:${utilityPct}%"><span>공무동(유틸동) 전력</span><b>${fmt(utilityPct,1)}%</b></div></div><div class="composition-legend"><div><i class="legend-dot direct-dot"></i><span><strong>설비 직접전력</strong><small>로 전력 + 外 설비 · ${fmt(directTotal)} kWh</small></span></div><div><i class="legend-dot utility-dot"></i><span><strong>공무동(유틸동) 전력</strong><small>예비소성·본소성 전력 비율 배부 · ${fmt(utilityTotal)} kWh</small></span></div></div>`}
function renderDonut(details){const by={};details.forEach(x=>by[x.r.line]=(by[x.r.line]||0)+x.total);const vals=Object.entries(by), sum=vals.reduce((s,x)=>s+x[1],0);let cursor=0;const stops=vals.map(([line,v],i)=>{const a=cursor;cursor+=v/sum*360;return `${palette[i%palette.length]} ${a}deg ${cursor}deg`}).join(',');donutChart.innerHTML=`<div class="donut" style="background:conic-gradient(${stops})"><div class="donut-center">${fmt(sum)}<small>총 kWh</small></div></div><div class="legend">${vals.map(([line,v],i)=>`<div class="legend-row"><i class="legend-dot" style="background:${palette[i%palette.length]}"></i>${line} · ${fmt(v/sum*100,1)}%</div>`).join('')}</div>`}
function renderBars(details){const by={};details.forEach(x=>{const p=x.r.product;if(!by[p])by[p]={e:0,q:0};by[p].e+=x.total;by[p].q+=Number(x.r.qty||0)});const vals=Object.entries(by).map(([p,v])=>[p,v.q?v.e/v.q:0]);const max=Math.max(...vals.map(x=>x[1]),1);barChart.innerHTML=vals.map(([p,v])=>`<div class="bar-row"><strong>${p}</strong><div class="bar-track"><div class="bar-fill" style="width:${v/max*100}%"></div></div><span class="bar-value">${fmt(v,3)}</span></div>`).join('')}
