function renderSettings(){modelSettingsEl.innerHTML=PROCESSES.flatMap(p=>(modelSettings[p.key]?.medians||p.medians).map((v,i)=>`<div class="setting-card"><strong>${p.name} · Class ${i+1}</strong><label>대표 중앙값 (kWh)<input type="number" data-setting="${p.key}" data-index="${i}" value="${v}"></label></div>`)).join('');modelSettingsEl.querySelectorAll('[data-setting]').forEach(el=>el.addEventListener('change',()=>{modelSettings[el.dataset.setting].medians[Number(el.dataset.index)]=Number(el.value);localStorage.setItem('power-model-settings-v2',JSON.stringify(modelSettings));status('모델 설정 저장됨',true)}))}
function renderProductSettings(){const processFields=[['pre','예비소성'],['mainA','본소성A/B'],['heat','열처리']];productSettingsEl.innerHTML=PRODUCT_OPTIONS.map(product=>{const t=productSettings[product]||PRODUCT_TEMPLATES[product];return `<div class="product-setting-card"><div class="product-setting-title"><strong>${product}</strong><span>제품 기본조건</span></div><div class="product-flow-fields"><label>CFA 유량<input type="number" min="0" step="0.1" data-product-setting="${product}" data-setting-field="cfa" value="${t.cfa}"></label><label>CDA 유량<input type="number" min="0" step="0.1" data-product-setting="${product}" data-setting-field="cda" value="${t.cda}"></label></div>${processFields.map(([key,label])=>{const c=t.conditions[key]||t.conditions.mainA||{fillTop:0,fillMid:0,fillBottom:0,time:0,temp:0};const enabled=t.enabled[key]!==false;return `<div class="product-process-setting"><div class="product-process-heading"><strong>${label}</strong><label><input type="checkbox" data-product-setting="${product}" data-setting-process="${key}" ${enabled?'checked':''}> 적용</label></div><div class="product-condition-fields"><label>상단<input type="number" step="0.1" data-product-setting="${product}" data-setting-process="${key}" data-setting-field="fillTop" value="${c.fillTop??0}"></label><label>중단<input type="number" step="0.1" data-product-setting="${product}" data-setting-process="${key}" data-setting-field="fillMid" value="${c.fillMid??0}"></label><label>하단<input type="number" step="0.1" data-product-setting="${product}" data-setting-process="${key}" data-setting-field="fillBottom" value="${c.fillBottom??0}"></label><label>소성시간 (hr)<input type="number" step="0.1" data-product-setting="${product}" data-setting-process="${key}" data-setting-field="time" value="${c.time??0}"></label><label>로 온도 (°C)<input type="number" step="1" data-product-setting="${product}" data-setting-process="${key}" data-setting-field="temp" value="${c.temp??0}"></label></div></div>`}).join('')}</div>`}).join('');productSettingsEl.querySelectorAll('[data-product-setting]').forEach(el=>el.addEventListener('change',()=>{const product=el.dataset.productSetting,t=productSettings[product];if(el.dataset.settingField==='cfa'||el.dataset.settingField==='cda')t[el.dataset.settingField]=Number(el.value)||0;else if(el.dataset.settingProcess){const key=el.dataset.settingProcess;if(el.dataset.settingField)t.conditions[key][el.dataset.settingField]=Number(el.value)||0;else if(el.type==='checkbox'){t.enabled[key]=el.checked;if(key==='mainA')t.enabled.mainB=el.checked}}saveProductSettings();LINES.forEach(line=>{if(document.getElementById(`product-${line}`)?.value===product)applyProductToLine(line,product)});status(`${product} 제품조건 저장됨`,true)}))}
function downloadExcel(){if(!lastResult){alert('먼저 산정 갱신을 눌러 계산하세요.');return}const resultRows=[['라인','제품','열처리 생산량(kg)','로 전력(kWh)','外 설비(kWh)','공무동(유틸동) 전력(kWh)','총전력(kWh)','전력원단위(kWh/kg)'],...lastResult.details.map(x=>[x.r.line,x.r.product,x.r.qty,x.furnace,x.aux,x.utility,x.total,x.intensity])];const inputRows=[['라인','제품','시작일','종료일','열처리 생산량(kg)','예비소성','본소성A/B','열처리'],...records.map(r=>[r.line,r.product,r.start,r.end,r.qty,...INPUT_PROCESSES.map(p=>(p.key==='mainA'?r.enabled.mainA&&r.enabled.mainB:r.enabled[p.key])?'생산':'미생산')])];const table=(title,rows)=>`<h2>${title}</h2><table border="1">${rows.map(r=>`<tr>${r.map(c=>`<td>${c??''}</td>`).join('')}</tr>`).join('')}</table>`;const html=`<html><meta charset="UTF-8"><body>${table(`전력 배부 결과 · ${monthPicker.value}`,resultRows)}${table('입력 생산 기록',inputRows)}</body></html>`;const blob=new Blob([html],{type:'application/vnd.ms-excel'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`전력배부결과_${monthPicker.value}.xls`;a.click();URL.revokeObjectURL(a.href)}
