function init(){const saved=loadState();monthPicker.value=saved?.month||'2026-07';seasonBadge.textContent=seasonFromMonth(monthPicker.value);renderLines(saved?.lines||{});records=normalizeRecords(saved?.records||LINES.map(line=>blankRecord(line)));renderRecords();renderConditions();renderProductSettings();renderSettings();activateTab('production');document.querySelectorAll('[data-tab-switch]').forEach(btn=>btn.addEventListener('click',()=>activateTab(btn.dataset.tabSwitch)));calculateBtn.addEventListener('click',calculate);downloadBtn.addEventListener('click',downloadExcel);monthPicker.addEventListener('change',()=>{seasonBadge.textContent=seasonFromMonth(monthPicker.value);renderRecords();renderConditions();saveState();status('산정 대상 월 변경 · 산정 갱신 필요')});resetBtn.addEventListener('click',()=>{if(confirm('입력값과 산정 결과를 초기화할까요?')){localStorage.removeItem(STORAGE_KEY);records=LINES.map(line=>blankRecord(line));renderLines();renderRecords();renderConditions();lastResult=null;status('입력 후 산정 갱신 필요');kpiGrid.innerHTML='';resultBody.innerHTML='';donutChart.innerHTML='';barChart.innerHTML=''}})}
const lineGrid=document.getElementById('lineGrid'),productionCards=document.getElementById('productionCards'),conditionCards=document.getElementById('conditionCards'),monthPicker=document.getElementById('monthPicker'),seasonBadge=document.getElementById('seasonBadge'),calculateBtn=document.getElementById('calculateBtn'),downloadBtn=document.getElementById('downloadBtn'),resetBtn=document.getElementById('resetBtn'),kpiGrid=document.getElementById('kpiGrid'),powerComposition=document.getElementById('powerComposition'),resultBody=document.getElementById('resultBody'),donutChart=document.getElementById('donutChart'),barChart=document.getElementById('barChart'),calculationStatus=document.getElementById('calculationStatus'),modelSettingsEl=document.getElementById('modelSettings'),productSettingsEl=document.getElementById('productSettings');
